export function wrap_NonSpecialToken(
	data: T._NonSpecialToken & { readonly $other?: T._NonSpecialToken | readonly T._NonSpecialToken[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	data = _keepModelledSlots(data, [
		'__literal',
		'_literal',
		'_string_literal',
		'_raw_string_literal',
		'_char_literal',
		'_boolean_literal',
		'_integer_literal',
		'_float_literal',
		'_identifier',
		'_mutable_specifier',
		'_self',
		'_super',
		'_crate',
		'__primitive_type',
		'_primitive_type',
		'__token_tree_punctuation',
		'_token_tree_punctuation',
		'__token_keywords',
		'_token_keywords'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'_literal',
		'literal',
		'string_literal',
		'raw_string_literal',
		'char_literal',
		'boolean_literal',
		'integer_literal',
		'float_literal',
		'identifier',
		'mutable_specifier',
		'self',
		'super',
		'crate',
		'_primitive_type',
		'primitive_type',
		'_token_tree_punctuation',
		'token_tree_punctuation',
		'_token_keywords',
		'token_keywords'
	]) as T._NonSpecialToken | readonly T._NonSpecialToken[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'_literal',
			'literal',
			'string_literal',
			'raw_string_literal',
			'char_literal',
			'boolean_literal',
			'integer_literal',
			'float_literal',
			'identifier',
			'mutable_specifier',
			'self',
			'super',
			'crate',
			'_primitive_type',
			'primitive_type',
			'_token_tree_punctuation',
			'token_tree_punctuation',
			'_token_keywords',
			'token_keywords'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T._NonSpecialToken>(data as T._NonSpecialToken, tree);
	}
	return drillIn<T._NonSpecialToken>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

