export function wrapCondition(
	data: T.Condition & { readonly $other?: T.Condition | readonly T.Condition[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	data = _keepModelledSlots(data, [
		'__expression',
		'_expression',
		'_unary_expression',
		'_reference_expression',
		'_try_expression',
		'_binary_expression',
		'_assignment_expression',
		'_compound_assignment_expr',
		'_type_cast_expression',
		'_call_expression',
		'_return_expression',
		'_yield_expression',
		'__literal',
		'_literal',
		'_string_literal',
		'_raw_string_literal',
		'_char_literal',
		'_boolean_literal',
		'_integer_literal',
		'_float_literal',
		'_identifier',
		'_self',
		'_scoped_identifier',
		'_generic_function',
		'_await_expression',
		'_field_expression',
		'_array_expression',
		'_tuple_expression',
		'_macro_invocation',
		'_unit_expression',
		'_break_expression',
		'_continue_expression',
		'_index_expression',
		'_metavariable',
		'_closure_expression',
		'_parenthesized_expression',
		'_struct_expression',
		'_unsafe_block',
		'_async_block',
		'_gen_block',
		'_try_block',
		'_block',
		'_if_expression',
		'_match_expression',
		'_while_expression',
		'_loop_expression',
		'_for_expression',
		'_const_block',
		'_range_expression',
		'_let_condition',
		'__let_chain',
		'_let_chain'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'_expression',
		'expression',
		'unary_expression',
		'reference_expression',
		'try_expression',
		'binary_expression',
		'assignment_expression',
		'compound_assignment_expr',
		'type_cast_expression',
		'call_expression',
		'return_expression',
		'yield_expression',
		'_literal',
		'literal',
		'string_literal',
		'raw_string_literal',
		'char_literal',
		'boolean_literal',
		'integer_literal',
		'float_literal',
		'identifier',
		'self',
		'scoped_identifier',
		'generic_function',
		'await_expression',
		'field_expression',
		'array_expression',
		'tuple_expression',
		'macro_invocation',
		'unit_expression',
		'break_expression',
		'continue_expression',
		'index_expression',
		'metavariable',
		'closure_expression',
		'parenthesized_expression',
		'struct_expression',
		'unsafe_block',
		'async_block',
		'gen_block',
		'try_block',
		'block',
		'if_expression',
		'match_expression',
		'while_expression',
		'loop_expression',
		'for_expression',
		'const_block',
		'range_expression',
		'let_condition',
		'_let_chain',
		'let_chain'
	]) as T.Condition | readonly T.Condition[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'_expression',
			'expression',
			'unary_expression',
			'reference_expression',
			'try_expression',
			'binary_expression',
			'assignment_expression',
			'compound_assignment_expr',
			'type_cast_expression',
			'call_expression',
			'return_expression',
			'yield_expression',
			'_literal',
			'literal',
			'string_literal',
			'raw_string_literal',
			'char_literal',
			'boolean_literal',
			'integer_literal',
			'float_literal',
			'identifier',
			'self',
			'scoped_identifier',
			'generic_function',
			'await_expression',
			'field_expression',
			'array_expression',
			'tuple_expression',
			'macro_invocation',
			'unit_expression',
			'break_expression',
			'continue_expression',
			'index_expression',
			'metavariable',
			'closure_expression',
			'parenthesized_expression',
			'struct_expression',
			'unsafe_block',
			'async_block',
			'gen_block',
			'try_block',
			'block',
			'if_expression',
			'match_expression',
			'while_expression',
			'loop_expression',
			'for_expression',
			'const_block',
			'range_expression',
			'let_condition',
			'_let_chain',
			'let_chain'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T.Condition>(data as T.Condition, tree);
	}
	return drillIn<T.Condition>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

