export function wrapPattern(
	data: T.Pattern & { readonly $other?: T.Pattern | readonly T.Pattern[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	data = _keepModelledSlots(data, [
		'__literal_pattern',
		'_literal_pattern',
		'_string_literal',
		'_raw_string_literal',
		'_char_literal',
		'_boolean_literal',
		'_integer_literal',
		'_float_literal',
		'_negative_literal',
		'_identifier',
		'_scoped_identifier',
		'_generic_pattern',
		'_tuple_pattern',
		'_tuple_struct_pattern',
		'_struct_pattern',
		'_ref_pattern',
		'_slice_pattern',
		'_captured_pattern',
		'_reference_pattern',
		'_remaining_field_pattern',
		'_mut_pattern',
		'_range_pattern',
		'_or_pattern',
		'_const_block',
		'_macro_invocation',
		'__wildcard_pattern',
		'_wildcard_pattern'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'_literal_pattern',
		'literal_pattern',
		'string_literal',
		'raw_string_literal',
		'char_literal',
		'boolean_literal',
		'integer_literal',
		'float_literal',
		'negative_literal',
		'identifier',
		'scoped_identifier',
		'generic_pattern',
		'tuple_pattern',
		'tuple_struct_pattern',
		'struct_pattern',
		'ref_pattern',
		'slice_pattern',
		'captured_pattern',
		'reference_pattern',
		'remaining_field_pattern',
		'mut_pattern',
		'range_pattern',
		'or_pattern',
		'const_block',
		'macro_invocation',
		'_wildcard_pattern',
		'wildcard_pattern'
	]) as T.Pattern | readonly T.Pattern[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'_literal_pattern',
			'literal_pattern',
			'string_literal',
			'raw_string_literal',
			'char_literal',
			'boolean_literal',
			'integer_literal',
			'float_literal',
			'negative_literal',
			'identifier',
			'scoped_identifier',
			'generic_pattern',
			'tuple_pattern',
			'tuple_struct_pattern',
			'struct_pattern',
			'ref_pattern',
			'slice_pattern',
			'captured_pattern',
			'reference_pattern',
			'remaining_field_pattern',
			'mut_pattern',
			'range_pattern',
			'or_pattern',
			'const_block',
			'macro_invocation',
			'_wildcard_pattern',
			'wildcard_pattern'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T.Pattern>(data as T.Pattern, tree);
	}
	return drillIn<T.Pattern>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

