export function wrapNonSpecialToken(
	data: T.NonSpecialToken & { readonly $other?: T.NonSpecialToken | readonly T.NonSpecialToken[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	data = _keepModelledSlots(data, [
		'__literal',
		'_literal',
		'_string_literal',
		'_raw_string_literal',
		'_char_literal',
		'_boolean_literal',
		'_integer_literal',
		'_float_literal',
		'_identifier',
		'_mutable_specifier',
		'_self',
		'_super',
		'_crate',
		'__primitive_type',
		'_primitive_type',
		'__token_tree_punctuation',
		'_token_tree_punctuation',
		'__token_keywords',
		'_token_keywords'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(data, [
		'_literal',
		'literal',
		'string_literal',
		'raw_string_literal',
		'char_literal',
		'boolean_literal',
		'integer_literal',
		'float_literal',
		'identifier',
		'mutable_specifier',
		'self',
		'super',
		'crate',
		'_primitive_type',
		'primitive_type',
		'_token_tree_punctuation',
		'token_tree_punctuation',
		'_token_keywords',
		'token_keywords'
	]) as T.NonSpecialToken | readonly T.NonSpecialToken[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(data.$other, [
			'_literal',
			'literal',
			'string_literal',
			'raw_string_literal',
			'char_literal',
			'boolean_literal',
			'integer_literal',
			'float_literal',
			'identifier',
			'mutable_specifier',
			'self',
			'super',
			'crate',
			'_primitive_type',
			'primitive_type',
			'_token_tree_punctuation',
			'token_tree_punctuation',
			'_token_keywords',
			'token_keywords'
		]);
	if (filtered === undefined && typeof (data as _NodeData).$text === 'string') {
		return drillInSelf<T.NonSpecialToken>(data as T.NonSpecialToken, tree);
	}
	return drillIn<T.NonSpecialToken>(
		normalizeSingularWrapSlot(filtered, 'children', true, data.$type, {
			tree,
			nodeType: data.$type,
			slotName: 'children',
			span: (data as _NodeData).$span
		}),
		tree
	);
}

